1	{
2	  "name": "cinescope",
3	  "$schema": "../../node_modules/nx/schemas/project-schema.json",
4	  "projectType": "application",
5	  "prefix": "app",
6	  "sourceRoot": "apps/cinescope/src",
7	  "tags": [],
8	  "targets": {
9	    "build": {
10	      "executor": "@angular/build:application",
11	      "outputs": [
12	        "{options.outputPath}"
13	      ],
14	      "defaultConfiguration": "production",
15	      "options": {
16	        "outputPath": "dist/apps/cinescope",
17	        "browser": "apps/cinescope/src/main.ts",
18	        "tsConfig": "apps/cinescope/tsconfig.app.json",
19	        "inlineStyleLanguage": "scss",
20	        "assets": [
21	          {
22	            "glob": "**/*",
23	            "input": "apps/cinescope/public"
24	          }
25	        ],
26	        "styles": [
27	          "apps/cinescope/src/styles.scss"
28	        ]
29	      },
30	      "configurations": {
31	        "production": {
32	          "budgets": [
33	            {
34	              "type": "initial",
35	              "maximumWarning": "500kb",
36	              "maximumError": "1mb"
37	            }
38	          ],
39	          "outputHashing": "all"
40	        },
41	        "development": {
42	          "optimization": false,
43	          "extractLicenses": false,
44	          "sourceMap": true
45	        }
46	      }
47	    },
48	    "serve": {
49	      "continuous": true,
50	      "executor": "@angular/build:dev-server",
51	      "defaultConfiguration": "development",
52	      "options": {
53	        "port": 4200
54	      },
55	      "configurations": {
56	        "production": {
57	          "buildTarget": "cinescope:build:production"
58	        },
59	        "development": {
60	          "buildTarget": "cinescope:build:development"
61	        }
62	      }
63	    },
64	    "lint": {
65	      "executor": "@nx/eslint:lint"
66	    },
67	    "test": {
68	      "executor": "@angular/build:unit-test",
69	      "options": {
70	        "watch": false
71	      }
72	    },
73	    "serve-static": {
74	      "continuous": true,
75	      "executor": "@nx/web:file-server",
76	      "options": {
77	        "buildTarget": "cinescope:build",
78	        "port": 4200,
79	        "staticFilePath": "dist/apps/cinescope/browser",
80	        "spa": true
81	      }
82	    }
83	  }
84	}
