import { describe, expect, it } from 'vitest';
import { buildAuditoriumRows } from './seat-layout';

describe('buildAuditoriumRows', () => {
  const rows = buildAuditoriumRows();

  it('has 15 rows', () => {
    expect(rows).toHaveLength(15);
  });

  it('has 308 selectable elements in total (seats + couches)', () => {
    const total = rows.reduce((sum, row) => sum + row.cells.filter((c) => c.kind === 'seat' || c.kind === 'couch').length, 0);
    expect(total).toBe(308);
  });

  it('rows 1-10 have 20 seats each (columns 5-24)', () => {
    for (const row of rows.slice(0, 10)) {
      const seats = row.cells.filter((c) => c.kind === 'seat');
      expect(seats).toHaveLength(20);
      expect(Math.min(...seats.map((s: any) => s.column))).toBe(5);
      expect(Math.max(...seats.map((s: any) => s.column))).toBe(24);
    }
  });

  it('rows 11-14 have 24 seats each', () => {
    for (const row of rows.slice(10, 14)) {
      expect(row.cells.filter((c) => c.kind === 'seat')).toHaveLength(24);
    }
  });

  it('row 15 has 12 couches and no seats', () => {
    const row15 = rows[14];
    expect(row15.cells.filter((c) => c.kind === 'couch')).toHaveLength(12);
    expect(row15.cells.filter((c) => c.kind === 'seat')).toHaveLength(0);
  });

  it('row 1 marks columns 10-15 as accessible', () => {
    const row1 = rows[0];
    const accessible = row1.cells.filter((c): c is any => c.kind === 'seat' && c.accessible);
    expect(accessible.map((c) => c.column).sort((a, b) => a - b)).toEqual([10, 11, 12, 13, 14, 15]);
  });

  it('every row has exactly two aisles', () => {
    for (const row of rows) {
      expect(row.cells.filter((c) => c.kind === 'aisle')).toHaveLength(2);
    }
  });
});

import { describe, expect, it } from 'vitest';
import { formatPrice, isAccessibleSeat, parseSeatId, priceForRow, seatId } from './seat.util';

describe('seat.util', () => {
  it('builds and parses seat identifiers', () => {
    expect(seatId(7, 12)).toBe('R7C12');
    expect(parseSeatId('R15C5')).toEqual({ row: 15, column: 5 });
  });

  it('prices rows per the spec table', () => {
    expect(priceForRow(1)).toBe(25);
    expect(priceForRow(5)).toBe(25);
    expect(priceForRow(6)).toBe(32);
    expect(priceForRow(10)).toBe(32);
    expect(priceForRow(11)).toBe(39);
    expect(priceForRow(14)).toBe(39);
    expect(priceForRow(15)).toBe(89);
  });

  it('formats prices with two decimals and PLN suffix', () => {
    expect(formatPrice(25)).toBe('25.00 PLN');
    expect(formatPrice(121)).toBe('121.00 PLN');
  });

  it('marks only row 1 columns 10-15 as accessible', () => {
    expect(isAccessibleSeat(1, 10)).toBe(true);
    expect(isAccessibleSeat(1, 15)).toBe(true);
    expect(isAccessibleSeat(1, 9)).toBe(false);
    expect(isAccessibleSeat(1, 16)).toBe(false);
    expect(isAccessibleSeat(2, 12)).toBe(false);
  });
});

import { describe, expect, it } from 'vitest';
import { formatShowDate, isValidIsoDate, toIsoDate } from './date.util';

describe('date.util', () => {
  it('formats a show date as "<Weekday> <D> <Mon> <HH:mm>"', () => {
    expect(formatShowDate('2026-09-15', '16:00')).toBe('Tuesday 15 Sep 16:00');
  });

  it('validates ISO dates strictly', () => {
    expect(isValidIsoDate('2026-09-15')).toBe(true);
    expect(isValidIsoDate('2026-13-01')).toBe(false);
    expect(isValidIsoDate('not-a-date')).toBe(false);
    expect(isValidIsoDate('2026-9-15')).toBe(false);
  });

  it('round-trips toIsoDate', () => {
    expect(toIsoDate(new Date(2026, 8, 15))).toBe('2026-09-15');
  });
});

import { describe, expect, it } from 'vitest';
import { groupIntoUnits, unitSeatLabel } from './selection.util';

describe('selection.util', () => {
  it('groups regular seats individually, ordered by row then column', () => {
    const units = groupIntoUnits(['R7C12', 'R7C11', 'R3C1']);
    expect(units.map((u) => [u.row, u.columns[0]])).toEqual([
      [3, 1],
      [7, 11],
      [7, 12],
    ]);
  });

  it('groups a couch pair into a single unit priced at 89', () => {
    const units = groupIntoUnits(['R15C1', 'R15C2']);
    expect(units).toHaveLength(1);
    expect(units[0].isCouch).toBe(true);
    expect(units[0].price).toBe(89);
    expect(unitSeatLabel(units[0])).toBe('Couch 1-2');
  });

  it('labels a regular seat by its column number', () => {
    const [unit] = groupIntoUnits(['R7C12']);
    expect(unitSeatLabel(unit)).toBe('12');
  });
});

import { beforeEach, describe, expect, it } from 'vitest';
import { BookingService } from './booking.service';

describe('BookingService', () => {
  beforeEach(() => {
    sessionStorage.clear();
  });

  it('starts a new empty booking for a screening', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    expect(service.booking()).toMatchObject({ screeningId: 1, seats: [], paid: false });
  });

  it('keeps the booking when reopening the same unpaid screening', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    service.toggleUnit(['R7C12']);
    service.ensureBookingForScreening(1);
    expect(service.booking()?.seats).toEqual(['R7C12']);
  });

  it('discards the previous booking when switching screenings', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    service.toggleUnit(['R7C12']);
    service.ensureBookingForScreening(2);
    expect(service.booking()).toMatchObject({ screeningId: 2, seats: [] });
  });

  it('toggles a seat on and off', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    expect(service.toggleUnit(['R7C12'])).toBe(true);
    expect(service.isSeatSelected('R7C12')).toBe(true);
    expect(service.toggleUnit(['R7C12'])).toBe(true);
    expect(service.isSeatSelected('R7C12')).toBe(false);
  });

  it('rejects a selection that would exceed 10 seats, without affecting the existing selection', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    for (let i = 1; i <= 10; i++) {
      expect(service.toggleUnit([`R2C${i}`])).toBe(true);
    }
    expect(service.toggleUnit(['R2C11'])).toBe(false);
    expect(service.seatCount()).toBe(10);
  });

  it('a couch counts as 2 seats and can push past the cap', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    for (let i = 1; i <= 9; i++) {
      service.toggleUnit([`R2C${i}`]);
    }
    expect(service.toggleUnit(['R15C1', 'R15C2'])).toBe(false);
    expect(service.seatCount()).toBe(9);
  });

  it('persists the booking in sessionStorage across instances', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    service.toggleUnit(['R7C12']);
    const reloaded = new BookingService();
    expect(reloaded.booking()?.seats).toEqual(['R7C12']);
  });

  it('clear() removes the booking', () => {
    const service = new BookingService();
    service.ensureBookingForScreening(1);
    service.clear();
    expect(service.booking()).toBeNull();
    expect(new BookingService().booking()).toBeNull();
  });
});

