export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface Customer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface Reservation {
  id: number;
  screeningId: number;
  seats: string[];
  customer: Customer;
  totalPrice: number;
}

export interface ReservationRequest {
  screeningId: number;
  seats: string[];
  customer: Customer;
  totalPrice: number;
}

export interface CheckoutFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface BookingState {
  screeningId: number;
  seats: string[];
  form: CheckoutFormValues;
  paid: boolean;
  customerEmail: string | null;
}

export function emptyCheckoutForm(): CheckoutFormValues {
  return {
    firstName: '',
    lastName: '',
    email: '',
    confirmEmail: '',
    phone: '',
    terms: false,
  };
}

export function emptyBooking(screeningId: number): BookingState {
  return {
    screeningId,
    seats: [],
    form: emptyCheckoutForm(),
    paid: false,
    customerEmail: null,
  };
}

export interface SeatPosition {
  row: number;
  column: number;
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): SeatPosition {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat identifier: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessibleSeat(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function isCouchRow(row: number): boolean {
  return row === 15;
}

export function priceForRow(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  if (row <= 14) return 39;
  return 89;
}

export function formatPrice(price: number): string {
  return `${price.toFixed(2)} PLN`;
}

export function couchColumns(seatA: string, seatB: string): [number, number] {
  const a = parseSeatId(seatA).column;
  const b = parseSeatId(seatB).column;
  return a < b ? [a, b] : [b, a];
}

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function toIsoDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

export function isValidIsoDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  const date = parseIsoDate(value);
  return !isNaN(date.getTime()) && toIsoDate(date) === value;
}

export function parseIsoDate(value: string): Date {
  const [year, month, day] = value.split('-').map(Number);
  return new Date(year, month - 1, day);
}

export function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

export function weekdayName(date: Date): string {
  return WEEKDAYS[date.getDay()];
}

export function formatShowDate(isoDate: string, time: string): string {
  const date = parseIsoDate(isoDate);
  const weekday = weekdayName(date);
  const month = MONTHS[date.getMonth()];
  return `${weekday} ${date.getDate()} ${month} ${time}`;
}

import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie } from '../models/movie.model';
import { Reservation, ReservationRequest } from '../models/reservation.model';
import { Screening } from '../models/screening.model';

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  getMovie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${BASE_URL}/movies/${id}`);
  }

  getScreenings(params?: { date?: string; movieId?: number }): Observable<Screening[]> {
    let httpParams = new HttpParams();
    if (params?.date) {
      httpParams = httpParams.set('date', params.date);
    }
    if (params?.movieId !== undefined) {
      httpParams = httpParams.set('movieId', params.movieId);
    }
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: httpParams });
  }

  getScreening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(request: ReservationRequest): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, request);
  }
}

import { Component, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA } from '@angular/material/snack-bar';

@Component({
  selector: 'app-toast',
  template: `<span data-testid="toast">{{ message }}</span>`,
  styles: [
    `
      :host {
        display: block;
      }
    `,
  ],
})
export class Toast {
  private readonly data = inject<{ message: string }>(MAT_SNACK_BAR_DATA);
  readonly message = this.data.message;
}

import { Injectable, inject } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { Toast } from '../shared/toast/toast';

@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(Toast, {
      data: { message },
      duration: 4000,
      horizontalPosition: 'center',
      verticalPosition: 'bottom',
    });
  }
}

import { Injectable, signal } from '@angular/core';
import { BookingState, CheckoutFormValues, emptyBooking } from '../models/booking.model';

const STORAGE_KEY = 'cinescope-booking';

@Injectable({ providedIn: 'root' })
export class BookingService {
  private readonly state = signal<BookingState | null>(this.load());
  readonly booking = this.state.asReadonly();

  private load(): BookingState | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return null;
    }
    try {
      return JSON.parse(raw) as BookingState;
    } catch {
      return null;
    }
  }

  private persist(value: BookingState | null): void {
    this.state.set(value);
    if (value) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(value));
    } else {
      sessionStorage.removeItem(STORAGE_KEY);
    }
  }

  /** Keeps the current booking when it is unpaid and belongs to this screening; otherwise starts a new, empty one. */
  ensureBookingForScreening(screeningId: number): void {
    const current = this.state();
    if (current && !current.paid && current.screeningId === screeningId) {
      return;
    }
    this.persist(emptyBooking(screeningId));
  }

  hasActiveBookingFor(screeningId: number): boolean {
    const current = this.state();
    return !!current && !current.paid && current.screeningId === screeningId && current.seats.length > 0;
  }

  hasPaidBooking(): boolean {
    return !!this.state()?.paid;
  }

  isSeatSelected(id: string): boolean {
    return this.state()?.seats.includes(id) ?? false;
  }

  seatCount(): number {
    return this.state()?.seats.length ?? 0;
  }

  /** Toggles a seat or couch (1 or 2 identifiers). Returns false when selecting would exceed the 10-seat cap. */
  toggleUnit(ids: string[]): boolean {
    const current = this.state();
    if (!current) {
      return false;
    }
    const selected = current.seats.includes(ids[0]);
    if (selected) {
      this.persist({ ...current, seats: current.seats.filter((id) => !ids.includes(id)) });
      return true;
    }
    if (current.seats.length + ids.length > 10) {
      return false;
    }
    this.persist({ ...current, seats: [...current.seats, ...ids] });
    return true;
  }

  removeUnit(ids: string[]): void {
    const current = this.state();
    if (!current) {
      return;
    }
    this.persist({ ...current, seats: current.seats.filter((id) => !ids.includes(id)) });
  }

  updateForm(partial: Partial<CheckoutFormValues>): void {
    const current = this.state();
    if (!current) {
      return;
    }
    this.persist({ ...current, form: { ...current.form, ...partial } });
  }

  markPaid(email: string): void {
    const current = this.state();
    if (!current) {
      return;
    }
    this.persist({ ...current, paid: true, customerEmail: email });
  }

  clear(): void {
    this.persist(null);
  }
}

