  const FAKE_NOW = new Date(2026, 8, 15, 10, 0, 0).getTime();
  const RealDate = Date;
  class FakeDate extends RealDate {
    constructor(...args) {
      if (args.length === 0) super(FAKE_NOW);
      else super(...args);
    }
    static now() {
      return FAKE_NOW;
    }
  }
  // eslint-disable-next-line no-global-assign
  Date = FakeDate;
});

