// Pin the browser's clock to a date inside db.json's screening range (15-21 Sep 2026),
// since the real sandbox clock is in October 2026 and the spec forbids changing date logic.
await page.addInitScript(() => {
  const FAKE_NOW = new Date(2026, 8, 15, 10, 0, 0).getTime();
  const RealDate = Date;
  class FakeDate extends RealDate {
    constructor(...args) {
      if (args.length === 0) super(FAKE_NOW);
      else super(...args);
    }
    static now() {
      return FAKE_NOW;
    }
  }
  // eslint-disable-next-line no-global-assign
  Date = FakeDate;
});

await page.goto('http://localhost:4200/', { waitUntil: 'networkidle' });

page.on('requestfailed', (r) => errors.push('requestfailed: ' + r.url() + ' ' + r.failure()?.errorText));
page.on('response', (r) => {
  if (r.url().includes('reservations')) {
    errors.push('response: ' + r.url() + ' ' + r.status());
  }
});

