  const seats = this.bookingService.booking()?.seats ?? [];
  const byRow = new Map<number, { sortKey: number; label: string }[]>();
  const seen = new Set<string>();
  for (const id of seats) {
    if (seen.has(id)) continue;
    const { row, column } = parseSeatId(id);
    if (isCouchRow(row)) {
      const otherColumn = column % 2 === 1 ? column + 1 : column - 1;
      const otherId = seatId(row, otherColumn);
      seen.add(id);
      seen.add(otherId);
      const [start, end] = couchColumns(id, otherId);
      const entries = byRow.get(row) ?? [];
      entries.push({ sortKey: start, label: `${start}-${end}` });
      byRow.set(row, entries);
    } else {
      seen.add(id);
      const entries = byRow.get(row) ?? [];
      entries.push({ sortKey: column, label: `${column}` });
      byRow.set(row, entries);
    }
  }
  return Array.from(byRow.entries())
    .sort((a, b) => a[0] - b[0])
    .map(([row, entries]) => ({
      row,
      label: entries
        .sort((a, b) => a.sortKey - b.sortKey)
        .map((e) => e.label)
        .join(', '),
    }));
});

